'use strict';const M=TabGroupsModel,U=OmniUI,$=id=>document.getElementById(id);let state,filter='all',selected=null,editing=null,busy=false,epoch=0;window.OMNI_PREVIEW=!window.omnibloomHost;const initial={version:1,revision:0,groups:[{id:'reading',name:'Reading',color:'blue'}],tabs:[{id:'guide',title:'A useful guide',url:'https://example.org/guide',groupId:'reading',pinned:true,private:false},{id:'studio',title:'Studio journal',url:'https://example.net/studio',groupId:null,pinned:false,private:false},{id:'learning',title:'Learning something new',url:'https://example.com/learning',groupId:'reading',pinned:false,private:false},{id:'private',title:'Private tab',url:'https://example.org/private',groupId:null,pinned:false,private:true}]};function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}function error(e){return({STALE_STATE:'Tabs changed. Reload and try again.',STORAGE_FULL:'Storage is full. No changes were saved.',PIN_LIMIT:'You can pin up to 16 tabs.',INVALID_TEXT:'Use a group name of 1 to 32 characters.',INVALID_STATE:'This tab collection could not be used.',MISSING_TAB:'That tab has closed.'})[e.code||e.message]||'Could not update tabs. Try again.'}
function draw(){const active=state.groups.some(g=>g.id===filter)||['all','pinned','ungrouped'].includes(filter);if(!active)filter='all';$('filters').replaceChildren();for(const [id,name]of [['all','All tabs'],['pinned','Pinned'],['ungrouped','Ungrouped'],...state.groups.map(g=>[g.id,g.name])]){const b=el('button','',name);b.dataset.filter=id;b.setAttribute('aria-pressed',String(filter===id));b.onclick=()=>{filter=id;draw();U.focus(document.querySelector('[data-filter="'+id+'"]'))};$('filters').append(b)}const visible=M.visible(state,filter);$('count').textContent=visible.length+' '+(visible.length===1?'tab':'tabs');$('tabs').replaceChildren();for(const t of visible){const card=el('article','tile'),open=el('button','open');open.dataset.id=t.id;open.append(el('span','pinned',(t.pinned?'Pinned':'')+(t.private?' · Private':'')),el('h2','',t.title),el('small','',t.url==='about:newtab'?'New tab':new URL(t.url).hostname));open.onclick=async()=>{try{await U.request('tabs.activate',{id:t.id,revision:state.revision},()=>({accepted:true}));U.notify(window.OMNI_PREVIEW?'Preview: tab selected.':'Tab selected.')}catch(e){U.notify(error(e))}};const group=state.groups.find(g=>g.id===t.groupId);if(group)open.append(el('span','group-mark color-'+group.color,group.name));const more=el('button','','More');more.setAttribute('aria-label','More options for '+t.title);more.onclick=()=>{selected=t.id;$('action-title').textContent=t.title;$('pin').textContent=t.pinned?'Unpin tab':'Pin tab';$('membership').replaceChildren();for(const [id,name]of [['','Ungrouped'],...state.groups.map(g=>[g.id,g.name])]){const o=el('option','',name);o.value=id;$('membership').append(o)}$('membership').value=t.groupId||'';U.modal('actions')};card.append(open,more);$('tabs').append(card)}if(!visible.length)$('tabs').append(el('p','empty','No tabs in this group.'));$('new-group').disabled=state.groups.length>=12;$('manage').disabled=state.groups.length===0}
async function mutate(operation){if(busy)return false;busy=true;const expected=state.revision,token=++epoch;try{M.apply(state,operation,expected);const result=await U.request('tabs.organize',{expectedRevision:expected,operation},()=>{const next=M.apply(state,operation,expected);M.persist(localStorage,next);return next});if(token!==epoch)return false;const next=M.validate(result);if(next.revision<=expected)throw Error('STALE_STATE');state=next;U.close();draw();U.focus($('new-group'));U.notify('Tabs updated.');return true}catch(e){U.notify(error(e));$('group-error').textContent=error(e);return false}finally{busy=false}}
function editGroup(g){editing=g?.id||null;$('group-title').textContent=g?'Edit group':'New group';$('group-name').value=g?.name||'';$('group-color').value=g?.color||'blue';$('group-error').textContent='';U.modal('group-editor')}$('new-group').onclick=()=>editGroup(null);$('save-group').onclick=()=>mutate({type:editing?'group.update':'group.create',group:{id:editing||'group-'+Date.now().toString(36),name:$('group-name').value,color:$('group-color').value}});$('pin').onclick=()=>{const t=state.tabs.find(t=>t.id===selected);if(t)mutate({type:'tab.pin',id:t.id,pinned:!t.pinned})};$('save-membership').onclick=()=>mutate({type:'tab.group',id:selected,groupId:$('membership').value||null});$('manage').onclick=()=>{$('group-list').replaceChildren();for(const g of state.groups){const row=el('section','group-row');row.append(el('h3','group-mark color-'+g.color,g.name));const actions=el('div','row'),edit=el('button','','Edit'),remove=el('button','danger','Remove group');edit.onclick=()=>{U.close();editGroup(g)};remove.onclick=()=>mutate({type:'group.delete',id:g.id});actions.append(edit,remove);row.append(actions);$('group-list').append(row)}U.modal('manager')};async function load(){try{const result=await U.request('tabs.list',{},()=>M.load(localStorage)||initial);state=M.validate(result);$('failure').hidden=true;draw();U.focus($('new-group'))}catch(_){$('failure').hidden=false;$('new-group').disabled=true;$('manage').disabled=true}}$('retry').onclick=load;window.addEventListener('omnibloom-event',e=>{if(e.detail?.event==='tabs.changed'){try{const next=M.validate(e.detail.payload);if(!state||next.revision>=state.revision){epoch++;state=next;U.close();draw();U.notify('Tabs changed.')}}catch(_){U.notify('Ignored an invalid tab update.')}}});load();
